#include <stdio.h>
int fact(int n) { return n <= 1 ? 1 : n * fact(n - 1); }
int main(void) { printf("%d\n", fact(4)); return 0; }

#include <stdio.h>
int fib(int n) {
    if (n < 2) return n;
    return fib(n - 1) + fib(n - 2);
}
int main(void) { printf("%d\n", fib(5)); return 0; }

#include <stdio.h>
void go(int n) {
    if (n == 0) return;
    printf("%d", n);
    go(n - 1);
}
int main(void) { go(3); return 0; }

#include <stdio.h>
int sd(int n) { return n == 0 ? 0 : n % 10 + sd(n / 10); }
int main(void) { printf("%d\n", sd(1234)); return 0; }

#include <stdio.h>
int gcd(int a, int b) { return b == 0 ? a : gcd(b, a % b); }
int main(void) { printf("%d\n", gcd(12, 18)); return 0; }

#include <stdio.h>
int a[3] = {2, 4, 6}, found = 0;
void go(int i, int s) {
    if (i == 3) { if (s == 10) found = 1; return; }
    go(i + 1, s + a[i]);
    go(i + 1, s);
}
int main(void) { go(0, 0); printf("%d\n", found); return 0; }

#include <stdio.h>
char used[3] = {0, 0, 0}, buf[4] = "ABC";
void perm(int d) {
    if (d == 3) { printf("%s\n", buf); return; }
    for (int i = 0; i < 3; i++)
        if (!used[i]) { used[i] = 1; buf[d] = 'A' + i; perm(d + 1); }
}
int main(void) { perm(0); return 0; }
